QieHuanMoShi_ = 0
QieHuanZhuangTai_ = 0

task0_finished = False
task1_finished = False

def customFunc1():
    global QieHuanMoShi_, QieHuanZhuangTai_
    while not (QieHuanZhuangTai_ == 1):
        if _camer.cam_dis_obj_id(2, 0, 0) == 1:
            _motor.mov_for_degrees("right", 0.5, "seconds")
            _motor.mov_for_degrees("left", 1, "seconds")
            _motor.mov_for_degrees("right", 0.5, "seconds")
            _os.sleep_s(1)
        if _camer.cam_dis_obj_id(2, 0, 0) == 2:
            _motor.run_for_degrees(1, "retreat", 1, "seconds")
            _os.sleep_s(0.5)
            _motor.run_for_degrees(1, "advance", 1, "seconds")
            _os.sleep_s(0.5)
        if _camer.cam_dis_obj_id(2, 0, 0) == 3:
            _motor.run_for_degrees(5, "retreat", 1, "seconds")
            _os.sleep_s(0.5)
            _motor.run_for_degrees(5, "advance", 1, "seconds")
            _os.sleep_s(0.5)
        if _camer.cam_dis_obj_id(2, 0, 0) == 4:
            _motor.mov_for_degrees("retreat", 1, "seconds")
            _motor.mov_for_degrees("advance", 1, "seconds")
            _os.sleep_s(1)
        _os.sleep_s(0.001)

def customFunc0():
    global QieHuanMoShi_, QieHuanZhuangTai_
    while not (QieHuanZhuangTai_ == 1):
        if _camer.cam_dis_obj_id(2, 1, 0) > 0:
            if _camer.cam_dis_id(2, 1, 1) < 200:
                _motor.mov_power(-55, 55, 0)
                _os.sleep_s(0.1)
            if _camer.cam_dis_id(2, 1, 1) > 400:
                _motor.mov_power(55, -55, 0)
                _os.sleep_s(0.1)
            if _camer.cam_dis_id(2, 1, 2) < 150:
                _motor.mov_power(55, 55, 0)
                _os.sleep_s(0.1)
            if _camer.cam_dis_id(2, 1, 2) > 250:
                _motor.mov_power(-55, -55, 0)
                _os.sleep_s(0.1)
            _motor.mov_stop()
        _os.sleep_s(0.001)

