def task0():
    global task0_finished
    global QieHuanMoShi_, QieHuanZhuangTai_
    _camer.changer_camer_mode(2, 6)
    _motor.pair(0,4)
    _motor.mov_set_stop_module(2)
    QieHuanMoShi_ = 1
    _matrix.show_roll(str(QieHuanMoShi_))
    while True:
        if QieHuanMoShi_ == 1:
            customFunc0()
        if QieHuanMoShi_ == 2:
            customFunc1()
        if QieHuanMoShi_ == 3:
            customFunc2()
        _os.sleep_s(0.001)
    task0_finished = True

def task1():
    global task1_finished
    global QieHuanMoShi_, QieHuanZhuangTai_
    while True:
        if _key.key_mast("left", 1):
            QieHuanMoShi_ += -1
            while not (_key.key_mast("left", 0)):
                _os.sleep_s(0.001)
            QieHuanZhuangTai_ = 1
        if _key.key_mast("right", 1):
            QieHuanMoShi_ += 1
            while not (_key.key_mast("right", 0)):
                _os.sleep_s(0.001)
            QieHuanZhuangTai_ = 1
        if QieHuanMoShi_ > 3:
            QieHuanMoShi_ = 1
        if QieHuanMoShi_ < 1:
            QieHuanMoShi_ = 3
        if QieHuanZhuangTai_ == 1:
            if QieHuanMoShi_ == 1:
                _camer.changer_camer_mode(2, 6)
                _matrix.show(0xbbff00, 0x7c,0x44,0x44,0x28,0x10,0x28,0x44,0x7c,0x7c)
                _os.sleep_s(13)
                _matrix.show(0xff004c, 0x00,0xc6,0x82,0x38,0x38,0x38,0x82,0xc6,0x00)
            if QieHuanMoShi_ == 2:
                _camer.changer_camer_mode(2, 21)
                _matrix.show(0xbbff00, 0x7c,0x44,0x44,0x28,0x10,0x28,0x44,0x7c,0x7c)
                _os.sleep_s(8)
                _matrix.show(0x2600ff, 0x00,0xc6,0xd6,0x28,0x54,0x28,0xd6,0xc6,0x00)
            if QieHuanMoShi_ == 3:
                _camer.changer_camer_mode(2, 18)
                _matrix.show(0xbbff00, 0x7c,0x44,0x44,0x28,0x10,0x28,0x44,0x7c,0x7c)
                _os.sleep_s(8)
                _matrix.show(0x00ffe5, 0x00,0x7c,0xee,0xce,0xee,0xee,0xc6,0x7c,0x00)
            QieHuanZhuangTai_ = 0
        _os.sleep_s(0.001)
    task1_finished = True

_thread.start_new_thread(task0, ())
_thread.start_new_thread(task1, ())

while not task0_finished or not task1_finished:
    _os.sleep_s(0.1)

